select.if:
SELECT ftl.flow_id,ftl.template_id,ftl.cur_link,ftl.link_type,ftl.pre_link,ftl.next_link,flc.link_name, flic.alarm_flow_id,afc.alarm_flow_name,flic.msg_notify_type,flic.user_type,flic.id as attr_id,flic.notify_admin_flag,flic.leader_flag FROM vm_flow_template_link ftl INNER JOIN vm_flow_link_config flc ON ftl.cur_link = flc.link_id INNER JOIN vm_alarm_flow_config afc ON ftl.tecmplate_id = afc.template_id LEFT JOIN vm_flow_link_attr flic ON ftl.cur_link = flic.link_id and flic.alarm_flow_id=afc.id WHERE afc.id = #{alarmFlowId}
AND ftl.cur_link = #{linkId}
AND ftl.real_link_type = #{realLinkType} and ftl.link_type='1'
